FreeSpiritEditor::~FreeSpiritEditor(){stopTimer();setLookAndFeel(nullptr);surface.setLookAndFeel(nullptr);}
void FreeSpiritEditor::resized(){surface.setTransform(juce::AffineTransform::scale(float(getWidth())/W,float(getHeight())/H));}
void FreeSpiritEditor::setTab(int t){selectedTab=t;for(auto& k:knobs)k.slider->setVisible(k.tab<0||k.tab==t);wave.setVisible(t==2);for(auto& b:buttons)if(b->getProperties().contains("tab"))b->setVisible(int(b->getProperties()["tab"])==t);update();}
void FreeSpiritEditor::choose(int i){p.loadPreset(i);preset=i;update();}
void FreeSpiritEditor::update(){int m=int(p.get("mode"));for(int i=0;i<12;i++)if(modes[i])modes[i]->setToggleState(i==m,juce::dontSendNotification);for(int i=0;i<7;i++)if(tabs[i])tabs[i]->setToggleState(i==selectedTab,juce::dontSendNotification);if(timing)timing->setToggleState(map,juce::dontSendNotification);if(presetLabel)presetLabel->setButtonText(p.presetName=="Custom sound"?"Unsaved changes":p.presetName);if(fav)fav->setButtonText(juce::String::fromUTF8(p.favorites.contains(p.presetName)?"★":"☆"));bool sy=p.get("sync")>.5;division.setVisible(sy);for(auto& b:buttons){if(b->getProperties().contains("timeL")){b->setVisible(!sy);b->setButtonText(juce::String(p.get("left"),0)+" ms");}if(b->getProperties().contains("timeR"))b->setButtonText(sy||p.get("link")>.5?"1 : "+juce::String(p.get("ratio"),2):juce::String(p.get("right"),0)+" ms");}surface.repaint();}
void FreeSpiritEditor::timerCallback(){update();}
