void FreeSpiritEditor::browse(){using namespace juce;PopupMenu root;root.addItem(1001,"Search presets...");root.addItem(1002,"Save user preset...");root.addItem(1003,"Load user preset...");root.addSeparator();PopupMenu f;for(size_t i=0;i<p.presets.size();++i)if(p.favorites.contains(p.presets[i].name))f.addItem(int(i+1),p.presets[i].name);root.addSubMenu("Favorites",f,!p.favorites.isEmpty());StringArray categories;for(auto& q:p.presets)categories.addIfNotAlreadyThere(q.category);for(auto cat:categories){PopupMenu sub;for(size_t i=0;i<p.presets.size();++i)if(p.presets[i].category==cat)sub.addItem(int(i+1),p.presets[i].name,true,int(i)==preset);root.addSubMenu(cat,sub);}auto safe=Component::SafePointer<FreeSpiritEditor>(this);root.showMenuAsync({},[safe](int n){if(safe==nullptr)return;if(n==1002)safe->save();else if(n==1003)safe->load();else if(n==1001){auto* w=new AlertWindow("Search factory sounds","Type a name or category",MessageBoxIconType::NoIcon);w->addTextEditor("query","");w->addButton("Search",1);w->addButton("Cancel",0);w->enterModalState(true,ModalCallbackFunction::create([safe,w](int r){if(safe==nullptr||r!=1)return;auto term=w->getTextEditorContents("query");PopupMenu results;for(size_t i=0;i<safe->p.presets.size();++i){auto& pr=safe->p.presets[i];if(pr.name.containsIgnoreCase(term)||pr.category.containsIgnoreCase(term))results.addItem(int(i+1),pr.name);}if(results.getNumItems()==0)results.addItem(1004,"No results",false);results.showMenuAsync({},[safe](int i){if(safe!=nullptr&&i>0&&i<=int(safe->p.presets.size()))safe->choose(i-1);});}),true);}else if(n>0&&n<=int(safe->p.presets.size()))safe->choose(n-1);});}
void FreeSpiritEditor::settings(){juce::PopupMenu m;m.addItem(1,"Safety limiter",true,p.get("safety")>.5);m.addItem(2,"Save preset...");m.addItem(3,"Load preset...");m.addItem(4,"Reset to defaults");auto safe=juce::Component::SafePointer<FreeSpiritEditor>(this);m.showMenuAsync({},[safe](int i){if(safe==nullptr)return;if(i==1)safe->p.set("safety",safe->p.get("safety")>.5?0:1);if(i==2)safe->save();if(i==3)safe->load();if(i==4)safe->p.reset();});}
void FreeSpiritEditor::save(){using namespace juce;chooser=std::make_unique<FileChooser>("Save FreeSpirit preset",File::getSpecialLocation(File::userDocumentsDirectory).getChildFile(p.presetName+".fspreset"),"*.fspreset");auto safe=Component::SafePointer<FreeSpiritEditor>(this);chooser->launchAsync(FileBrowserComponent::saveMode|FileBrowserComponent::canSelectFiles|FileBrowserComponent::warnAboutOverwriting,[safe](const FileChooser& c){if(safe==nullptr)return;auto f=c.getResult();if(f==File{})return;f=f.withFileExtension(".fspreset");MemoryBlock b;safe->p.getStateInformation(b);if(f.replaceWithData(b.getData(),b.getSize()))safe->p.presetName=f.getFileNameWithoutExtension();});}
void FreeSpiritEditor::load(){using namespace juce;chooser=std::make_unique<FileChooser>("Load FreeSpirit preset",File::getSpecialLocation(File::userDocumentsDirectory),"*.fspreset");auto safe=Component::SafePointer<FreeSpiritEditor>(this);chooser->launchAsync(FileBrowserComponent::openMode|FileBrowserComponent::canSelectFiles,[safe](const FileChooser& c){if(safe==nullptr)return;MemoryBlock b;if(c.getResult().loadFileAsData(b)){safe->p.setStateInformation(b.getData(),int(b.getSize()));safe->p.presetName=c.getResult().getFileNameWithoutExtension();safe->preset=-1;safe->update();}});}
